import { useState } from 'react';

export function Contacto() {
  const [form, setForm] = useState({ nombre: '', email: '', mensaje: '' });
  const [enviado, setEnviado] = useState(false);

  function cambiar(e) {
    setForm({ [e.target.name]: e.target.value });
  }

  async function enviar(e) {
    e.preventDefault();
    await fetch('/api/contacto', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify(form),
    });
    setEnviado(true);
  }

  if (enviado) return <p>¡Gracias! Te responderemos pronto.</p>;

  return (
    <form onSubmit={enviar}>
      <label htmlFor="nombre">Nombre</label>
      <input id="nombre" name="nombre" value={form.nombre} onChange={cambiar} required />
      <label htmlFor="email">Email</label>
      <input id="email" name="email" value={form.email} onChange={cambiar} required />
      <label htmlFor="msj">Mensaje</label>
      <textarea id="mensaje" name="mensaje" value={form.mensaje} onChange={cambiar} required />
      <button type="submit">Enviar</button>
    </form>
  );
}
